import { useState } from 'react';
import { JxTagInput, JxChip } from '@jinx-ui/react';

interface ArticleTagPickerProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({ value, defaultValue = [], onChange }: ArticleTagPickerProps) {
  const [internalTags, setInternalTags] = useState<string[]>(defaultValue);
  const tags = value ?? internalTags;

  const update = (next: string[]) => {
    if (value === undefined) setInternalTags(next);
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <JxTagInput
        ariaLabel="Теги статьи"
        placeholder="Введите тег и нажмите Enter"
        value={tags}
        onValueChange={update}
      />
      {tags.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
          {tags.map((tag) => (
            <JxChip key={tag} removable onRemove={() => update(tags.filter((item) => item !== tag))}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

